from pathlib import Path
def describe_path(path):
    p = Path(path)
    return p.name, p.suffix, p.exists()

import argparse
def parse_flags(argv):
    parser = argparse.ArgumentParser()
    parser.add_argument("--limit",type=int,default=5)
    parser.add_argument("--no-fast-plays",action="store_true")
    return parser.parse_args(argv)

from datetime import datetime, timezone
def utc_day(text):
    return datetime.fromisoformat(text).astimezone(timezone.utc).date().isoformat()

from collections import Counter
import hashlib
def audit_labels(labels):
    return dict(Counter(labels)), hashlib.sha256("\n".join(labels).encode("utf-8")).hexdigest()

import subprocess
import sys
def child_summary():
    result = subprocess.run([sys.executable,"-B","-c","print(6 - 3)"],capture_output=True,text=True,timeout=5)
    return result.returncode, result.stdout.strip()
